"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["78937"],{97882(e){e.exports=JSON.parse('{"id":"FIN-100","slug":"journal-entry","term":"Journal Entry","also_known_as":[],"difficulty":"Beginner","definition":"A journal entry is the record of a single business transaction, showing the date, the accounts affected, the amounts debited and credited and a short description.","explanation":["A journal entry is the first step in recording a transaction in double-entry bookkeeping. It shows which accounts change and by how much, with total debits always equal to total credits.","Suppose a business pays 1,500 of rent from its bank account on 1 March. The journal entry would show a debit of 1,500 to rent expense and a credit of 1,500 to cash, with the date and a note such as \\"March office rent\\".","Journal entries are listed in the order transactions happen, in a record called the journal. They are then posted to individual accounts in the general ledger.","Besides everyday transactions, accountants make special journal entries at the end of each period. Adjusting entries record items such as accrued expenses and depreciation. Closing entries reset revenue and expense accounts for the next period. Each journal entry should be supported by evidence, such as an invoice, receipt or contract, so that it can be checked later by managers or auditors."],"note":"","total":1500,"prev":{"slug":"joint-venture","term":"Joint Venture"},"next":{"slug":"key-performance-indicator","term":"Key Performance Indicator (KPI)"}}')}}]);